import {scenarioNames} from './training-options.js';
import {createVeteranSearch} from './veteran-search.js';
import {createSearchUI} from './search-ui.js';
import {createReference} from './reference.js';
import {Engine,aptitudes,grades,stats,categories,baseId,normalizeImport,emptyNode,emptyPlan,placeVeteran,validateTree,creationChance,baselineEvaluation} from './core.js';
import {readState,writeState} from './storage.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const jointPct=n=>n===null?'—':n===0?'0%':n<.0001?`${(n*100).toExponential(2)}%`:`${(n*100).toFixed(3)}%`;
const runs=n=>n===null?'—':!Number.isFinite(n)?'∞ (impossible in model)':Number(n.toPrecision(3)).toLocaleString(undefined,{maximumFractionDigits:1});
const pct=n=>`${(n*100).toFixed(1)}%`, number=n=>Number(n||0).toLocaleString();
const labels=['Target trainee','Parent 1','Parent 2','P1 · Grandparent 1','P1 · Grandparent 2','P2 · Grandparent 1','P2 · Grandparent 2',...Array.from({length:8},(_,i)=>`Next generation ${i+1}`)];
let veteranSearch,searchUI,plannerFiltersOpen=false;
let ref,D,engine,state,route,worker,results=null,pickerIndex=0,pickerKind='veterans',detailId=null,toastTimer;
let collection={kind:'veterans',query:'',spark:'',minStars:1,scope:'self',aptitude:'',grade:7,sort:'rating',page:0,type:''};
let skillQuery='',skillPage=0;
const skillFilters={category:'',rarity:'',condition:'',wit:'',owned:false};
const initial=()=>({schema:1,collections:{trainees:[],supports:[],veterans:[]},imports:{},plan:emptyPlan(),saved:[]});
const char=id=>D.characters.find(c=>c.cardId===Number(id));
const charName=id=>char(id)?.charaName??D.characters.find(c=>c.charaId===baseId(id))?.charaName??`Character ${baseId(id)}`;
const outfit=id=>char(id)?.cardTitle??`Card #${id}`;
const title=id=>`${charName(id)} ${outfit(id)}`;
const support=id=>D.supports.find(c=>c.supportCardId===Number(id));
const factor=id=>engine.factors.get(Number(id));
const sparkName=id=>factor(id)?.text??`Unknown spark ${id}`;
const skill=id=>D.skills.find(s=>s.skillId===Number(id));
const metaOptions=(items,valueFn,labelFn,selected='')=>items.map(x=>`<option value="${esc(valueFn(x))}" ${String(valueFn(x))===String(selected)?'selected':''}>${esc(labelFn(x))}</option>`).join('');
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5500);}
async function save(){try{await writeState(state);}catch(e){notify('Browser storage failed. Export a backup now to keep your changes.');}}
function invalidate(){results=null;if(worker){worker.terminate();worker=null;}save();}
function sparks(items,limit=99){return `<div class="chips">${items.slice(0,limit).map(f=>`<span class="chip type-${factor(f.id)?.type??-1}" title="${esc(sparkName(f.id))}">${esc(sparkName(f.id))} <b>${'★'.repeat(f.stars)}</b></span>`).join('')}${items.length>limit?`<span class="chip">+${items.length-limit}</span>`:''}</div>`;}
function heading(kicker,name,desc,actions=''){return `<div class="title-row"><div><div class="eyebrow">${kicker}</div><h1>${name}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function go(){route=location.hash.slice(1)||'planner';if(!['planner','collection','skills','data'].includes(route))route='planner';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));$('#breadcrumb').textContent=`WORKSPACE / ${route.toUpperCase()}`;render();}
function render(){if(!D)return;$('#main').innerHTML=({planner:renderPlanner,collection:renderCollection,skills:renderSkills,data:renderData}[route])();if(route==='collection')renderRows();if(route==='skills')renderSkillRows();if(route==='planner'&&results)renderResults();}
function nodeMarkup(n,i,ev){const filled=!!n.cardId;return `<div class="node ${i===0?'target-node':''} ${filled?'':'empty-node'}"><div class="node-label">${labels[i]} ${i>0&&i<3?`<label class="check" title="Keep this imported parent during search"><input type="checkbox" data-pin="${i-1}" ${state.plan.pins[i-1]?'checked':''} aria-label="Pin parent ${i}"></label>`:''}</div><div class="avatar">${filled?ref.portrait(n.cardId):'＋'}</div><div class="node-name">${filled?esc(charName(n.cardId)):'Choose a character'}</div><div class="node-outfit">${filled?esc(outfit(n.cardId)):'From your roster or plan ahead'}</div>${sparks(n.sparks,i>2?2:3)}<div class="node-bottom">${filled?(n.sourceId?'Imported veteran':'Planned / ancestor snapshot'):'Empty slot'}${i>0&&i<7&&filled?` · ${state.plan.nodes[0].cardId?`${ev.slots[i]} affinity`:'affinity off'}`:''}</div><div class="node-tools"><button data-edit="${i}">${filled?'Edit':'Choose'}</button>${filled?`<button data-clear-node="${i}" aria-label="Clear ${labels[i]}">×</button>`:''}</div></div>`;}
function renderPlanner(){const p=state.plan,ev=p.nodes[0].cardId?engine.evaluate(p.nodes,p.parentRaceBonus):baselineEvaluation(p.nodes),odds=engine.odds(p.nodes,ev,p.rolls),white=odds.filter(o=>factor(o.id)?.type===3);const counts=state.collections;
return heading('PLAN / INHERIT / REFINE','Build your next generation.','Bring your roster together. Find the parents worth training with.',`<button data-action="new-plan">New plan</button><button data-action="export-plan">Export plan</button>`)+
`<div class="stats-row"><div class="metric"><span>VETERANS IN YOUR ROSTER</span><b>${number(counts.veterans.length)}</b><span>${counts.trainees.length} trainees · ${counts.supports.length} support cards</span></div><div class="metric"><span>LINEAGE COMPATIBILITY</span><b class="green">${p.nodes[0].cardId?ev.total:'—'} <small style="font-size:13px">${p.nodes[0].cardId?(ev.total>=151?'◎':ev.total>=51?'○':'△'):''}</small></b><span>${!p.nodes[0].cardId?'Affinity excluded · no target':ev.complete?'Complete character tree':'Provisional · incomplete tree'}</span></div><div class="metric"><span>DESIRED SPARKS</span><b>${p.wanted.length}</b><span>${p.rolls===2?'Across both inheritance events':'Per inheritance event'}</span></div></div>
${!counts.veterans.length?`<div class="notice">Start by importing your three umadump files. You can also plan characters and sparks manually. <button class="small" data-action="import">Import JSON</button></div>`:''}
<details class="panel" id="planner-filters" ${plannerFiltersOpen?'open':''}><summary>Candidate filters · Basic / Advanced / UQL</summary>${searchUI.markup('planner')}</details><div class="planner-layout"><div><section class="panel"><div class="panel-head"><h2>Lineage workspace</h2><span class="badge">${p.parentRaceBonus?'PARENT–PARENT G1 ON':'GLOBAL · PARENT–PARENT G1 OFF'}</span></div><p class="tiny">Choose the target, then two veterans. Their parents fill the grandparent slots automatically.</p><div class="tree"><div class="tree-row target">${nodeMarkup(p.nodes[0],0,ev)}</div><div class="tree-row parents">${p.nodes.slice(1,3).map((n,i)=>nodeMarkup(n,i+1,ev)).join('')}</div><div class="tree-row grandparents">${p.nodes.slice(3,7).map((n,i)=>nodeMarkup(n,i+3,ev)).join('')}</div></div><details><summary>Plan the next generation · 8 additional slots</summary><p class="tiny">These slots help plan future grandparents. They do not contribute directly to this target’s inheritance odds.</p><div class="generation3">${p.nodes.slice(7).map((n,i)=>nodeMarkup(n,i+7,ev)).join('')}</div></details>${ev.issues.length?`<div class="notice warning">${ev.issues.map(esc).join('<br>')}</div>`:''}<details><summary>Compatibility breakdown & calculation rules</summary><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Direct</th><th>Three-way</th><th>G1 bonus</th></tr></thead><tbody>${ev.branches.map((b,i)=>`<tr><td>Parent ${i+1}</td><td>${b.direct}</td><td>${b.triples}</td><td>${b.race}</td></tr>`).join('')}<tr><td>Parent pair</td><td>${ev.pair}</td><td>—</td><td>${ev.pairRace}</td></tr></tbody></table></div><p class="tiny">Shared G1 groups count once per relationship, at +3 each. Each parent’s spark odds use its branch plus the parent-pair relation. Each grandparent uses its three-way relation plus its shared G1 bonus with its parent. Missing race histories can understate these values.</p><label class="check"><input type="checkbox" id="parent-race" ${p.parentRaceBonus?'checked':''}> Include parent-to-parent shared-G1 bonus (alternate / JP-style rule)</label><p class="tiny">The bundled catalog is Global. This switch changes one rule; it does not provide a complete JP data mode. Community calculations are estimates, not guaranteed game outcomes.</p></details></section>
<section class="panel"><div class="panel-head"><h2>Inheritance odds</h2><label><select id="rolls" aria-label="Inheritance period"><option value="2" ${p.rolls===2?'selected':''}>Both events</option><option value="1" ${p.rolls===1?'selected':''}>One event</option></select></label></div><p class="tiny">Chance of receiving each spark at least once. Starting inheritance is excluded; sources roll independently.</p>${!ev.complete?'<div class="notice warning">Complete a valid seven-character tree to display percentages.</div>':odds.length?`<div class="table-wrap"><table><thead><tr><th>Spark</th><th>Copies / stars</th><th>At least once</th><th>At least twice</th></tr></thead><tbody>${odds.map(o=>`<tr><td>${esc(sparkName(o.id))}<span class="row-sub">${categories[factor(o.id)?.type]??'Unknown'}</span></td><td>${o.copies} / ${o.stars}★</td><td class="percent">${pct(o.chance)}<div class="bar"><span style="width:${o.chance*100}%"></span></div></td><td>${pct(Math.max(0,o.twice))}</td></tr>`).join('')}</tbody></table></div>`:'<p>Add parent or grandparent sparks to see their odds.</p>'}<details><summary>White-spark creation after training</summary><p class="tiny">A separate model: chance to generate a white skill spark after finishing a career, conditional on learning the corresponding skill. Each lineage copy multiplies the base chance by 1.1. This does not predict star level or skill availability.</p>${white.length?`<div class="table-wrap"><table><thead><tr><th>Skill spark</th><th>Copies</th><th>Learned ○</th><th>Learned ◎</th><th>Learned gold</th></tr></thead><tbody>${white.map(o=>`<tr><td>${esc(sparkName(o.id))}</td><td>${o.copies}</td><td>${pct(creationChance(o.copies))}</td><td>${pct(creationChance(o.copies,'upgraded'))}</td><td>${pct(creationChance(o.copies,'gold'))}</td></tr>`).join('')}</tbody></table></div>`:'<p>No white skill sparks selected.</p>'}</details></section><section id="results" class="search-results"></section></div>
<aside class="panel side-panel" style="height:auto;color:inherit;background:var(--cream);padding:22px"><div class="eyebrow">SEARCH YOUR ROSTER</div><h2>Find my parents</h2><p>${p.includeSupports?'Rank parent-and-deck matches by the selected skill / training-value balance.':'Rank eligible pairs by the lowest desired-spark chance, then combined chances, then compatibility.'}</p><hr><label class="check"><input id="include-supports" type="checkbox" ${p.includeSupports?'checked':''}> Include support cards</label>${p.includeSupports?`<div class="notice"><b>Five owned + one borrowed support</b><p class="tiny">Searches skill coverage for end-of-career spark creation. Hints, events and awakening skills are potential sources, not guaranteed unlocks. Veterans contribute their recorded sparks; learned skills alone cannot be inherited. Deck search is approximate; training value uses the Euophrys expectation model.</p><label class="check"><input id="borrow-ssr" type="checkbox" ${p.borrowSSR!==false?'checked':''}> Borrow SSR only (assume MLB / max level)</label>${trainingControls()}<p class="tiny">Uncheck SSR only to allow any rarity. Cards sharing a character, or matching the target, cannot be used together. Without a target, recheck deck legality when choosing one.</p></div>`:''}<div class="filter-grid"><div><label>Desired spark<input id="wanted-search" list="factor-list" placeholder="Type a name or ID…"></label><datalist id="factor-list">${[...engine.factors].map(([id,f])=>`<option value="${esc(f.text)} (#${id})"></option>`).join('')}</datalist><button class="small" data-action="add-wanted">＋ Add spark</button><div>${p.wanted.map(id=>`<div class="wanted"><span>${esc(sparkName(id))}</span><button data-remove-wanted="${id}" aria-label="Remove ${esc(sparkName(id))}">×</button></div>`).join('')}</div></div><div><label>Search outcome<select id="search-mode" ${p.includeSupports?'disabled':''}><option value="inherit" ${p.searchMode!=='sparkgen'&&!p.includeSupports?'selected':''}>Inspiration · inherit sparks</option><option value="sparkgen" ${p.searchMode==='sparkgen'||p.includeSupports?'selected':''}>Spark % · after this career</option></select></label>${boughtMarkup()}${p.deck?.length?`<details><summary>Applied support deck</summary><p class="tiny">Saved deck snapshot. Rerun the search after changing target, skills, or scenario settings.</p>${deckMarkup(p.deck,[],p.training)}</details>`:''}<p class="inline-note">Pin either imported parent to search around it. ${p.includeSupports?'Without a target, affinity and race bonuses are excluded and growth is neutral; support sources still count. With no desired sparks, decks rank by training value.':'Without a target, all affinity and race bonuses are excluded; only recorded sparks count. With no desired sparks, only affinity ranks pairs; without a target those pairs tie.'} With a target, complete ancestry and known compatibility are required.</p></div></div><button class="primary" data-action="find-parents" ${!counts.veterans.length?'disabled':''}>${p.includeSupports?'Find parents & deck':'Find parent pairs'} →</button><div id="search-status"></div><hr><h3>Save this plan</h3><div class="save-row"><input id="plan-name" aria-label="Plan name" value="${esc(p.name)}"></div><button class="full" data-action="save-plan">Save snapshot</button><div>${state.saved.map((s,i)=>`<div class="saved-plan"><button class="small" data-load-plan="${i}">${esc(s.name)}</button><button class="small danger" data-delete-plan="${i}" aria-label="Delete ${esc(s.name)}">×</button></div>`).join('')}</div></aside></div>`;}
function trainingControls(){const p=state.plan,g=char(p.nodes[0].cardId);return `<div class="training-controls"><label>Training scenario<select id="training-scenario">${metaOptions([['auto','Automatic · best modeled value'],...Object.entries(scenarioNames)],x=>x[0],x=>x[1],p.scenario??'auto')}</select></label><details><summary>Scenarios to compare automatically</summary>${Object.entries(scenarioNames).map(([id,name])=>`<label class="check"><input type="checkbox" data-auto-scenario="${id}" ${(p.autoScenarios??['URA','Aoharu','MANT','GL']).includes(id)?'checked':''}> ${esc(name)}</label>`).join('')}<p class="tiny">Enable only scenarios available to you. Grand Masters is opt-in. Automatic compares these presets; a manual choice overrides this list.</p></details><label>Training focus<select id="training-focus">${metaOptions(['balanced','speed','stamina','power','guts','wisdom'],x=>x,x=>x==='wisdom'?'Wit':x,p.trainingFocus??'balanced')}</select></label><label>Training-value weight<select id="training-weight">${metaOptions([0,10,25,50,75,100],x=>x,x=>`${x}% training / ${100-x}% skills`,p.trainingWeight??25)}</select></label><p class="tiny">Growth: ${g?['Speed','Stamina','Power','Guts','Wisdom'].map(k=>`${k} +${g['talent'+k]??0}%`).join(' · '):'no target → neutral (0%)'}. Owned cards are modeled at their current limit-break cap, assuming you level them; the displayed level is your imported level. Borrowed cards are MLB at max level. Training value is a relative index, not predicted final stats.</p></div>`;}
function trainingMarkup(t,score){return `<div class="training-summary"><b>${esc(scenarioNames[t.scenario]??'Training model unavailable')}</b>${score!=null?` · combined score ${score.toFixed(1)}`:''}<span class="row-sub">Training index ${number(Math.round(t.score))}${t.neutralGrowth?' · neutral growth':''}</span><details><summary>Scenario comparison & card contributions</summary>${t.comparisons.map(c=>`<p class="tiny">${esc(scenarioNames[c.scenario])}: ${number(Math.round(c.score))}</p>`).join('')}${(t.perCard??[]).map(c=>`<p class="tiny">${esc(support(c.id)?.charaName??c.id)}: ${number(Math.round(c.score))}</p>`).join('')}${t.missing.length?`<p class="tiny">No model for cards: ${t.missing.map(esc).join(', ')}</p>`:''}<p class="tiny">Sum of each card’s marginal score with the other five fixed; not a full-career simulation. Common stat weights allow scenario comparison. Best found in a bounded search, not a guaranteed global optimum.</p></details></div>`;}
function deckMarkup(cards,acquisition=[],training=null,combined=null){return `${training?trainingMarkup(training,combined):''}`+`<div class="match-deck">${cards.map(c=>{const meta=support(c.id);return `<div class="deck-card">${ref.supportArt(c.id)}<span>${esc(meta?.charaName??c.id)}<br><b>${c.borrowed?'Borrowed · MLB':'Owned · '+c.limitBreak+'/4 LB'}</b><br>${esc(meta?.rarityDisplay??'')} · Lv ${c.level??'?'} · ${esc(meta?.supportCardTypeName??'')}</span></div>`;}).join('')}</div>${acquisition.length?`<details><summary>Skill sources & assumptions</summary>${acquisition.map((a,i)=>`<p class="tiny"><b>${esc(sparkName(state.plan.wanted[i]))}</b>: ${a.kind==='inspiration'?`Inspiration required (${pct(a.chance)})`:a.kind==='inheritance'?'Inheritance only':`${esc(a.skillName)} · ${a.kind.startsWith('support')?esc(support(a.entityId)?.charaName??a.entityId):esc(charName(a.entityId))} · ${esc(a.detail)}${a.borrowed?' · borrowed':''} (conditional)`}</p>`).join('')}<p class="tiny">Source access does not model hint RNG, event completion, skill-point cost, or awakening unlocks. Confirm those before training. Normal/gold source tier is chosen automatically; Inspiration only overrides deck access.</p></details>`:''}`;}
function renderResults(){const el=$('#results');if(!el||!results)return;if(state.plan.includeSupports&&$('.planner-layout'))$('.planner-layout').after(el);el.innerHTML=`<div class="panel"><div class="panel-head"><h2>${state.plan.includeSupports?'Parent matches & deck':'Parent matches'}</h2><span class="badge">${number(results.matched)} eligible pairs</span></div><details><summary>How to read these estimates</summary><p class="tiny">${state.plan.includeSupports?'Skill columns show end-of-career creation chances, conditional on learning the listed support or character skill. Deck search balances skill coverage with a relative training-value model; hint/event success remains unmodeled. ':''}${state.plan.searchMode==='sparkgen'||state.plan.includeSupports?'Skill columns show end-of-career spark chances; other spark types show inheritance odds.':'Columns show inheritance odds.'} ${!state.plan.nodes[0].cardId?'Affinity-free baseline; not target-specific career odds.':''} Average chance is the arithmetic mean of the requested chances. All-in-one-run odds multiply distinct outcomes, assuming independence; interchangeable forms count once. Average runs = 1 ÷ all-in-one-run probability, assuming identical independent attempts. This is an estimate, not a guarantee; one-event mode covers only that event. With no desired sparks, summaries are unavailable. Best ${results.top.length} shown. Search uses imported veterans and their captured ancestors; manually edited grandparent slots are replaced when a pair is applied.</p></details>${!results.top.length?'<div class="empty"><h2>No matching pair</h2><p>Remove a pin or import more veterans. With a target selected, complete ancestry and known compatibility are required.</p></div>':`<div class="table-wrap"><table><thead><tr><th>Parents${state.plan.includeSupports?' & deck':''}</th><th>Affinity</th><th>Average chance</th><th>All in one run ≈</th><th>Average runs ≈</th>${state.plan.wanted.map(id=>`<th>${esc(sparkName(id))}</th>`).join('')}<th></th></tr></thead><tbody>${results.top.map((r,i)=>{const a=state.collections.veterans.find(v=>v.id===r.a),b=state.collections.veterans.find(v=>v.id===r.b);return `<tr><td class="name">${esc(charName(a.cardId))} + ${esc(charName(b.cardId))}<span class="row-sub">Veteran #${esc(a.id)} + #${esc(b.id)}</span>${r.deck?deckMarkup(r.deck,r.acquisition,r.training,r.combinedScore):''}</td><td>${r.baseline?'Not used':r.total}</td><td class="percent">${r.average===null?'—':pct(r.average)}</td><td>${jointPct(r.allChance)}</td><td>${runs(r.expectedRuns)}</td>${r.chances.map(c=>`<td class="percent">${pct(c)}</td>`).join('')}<td><button class="small" data-apply-pair="${i}">Use pair</button></td></tr>`}).join('')}</tbody></table></div>`}</div>`;}
function renderCollection(){return heading('YOUR ROSTER','A collection with context.','Browse what you own, filter veterans, and bring candidates into your lineage.',`<button data-action="export-backup">Export backup</button>`)+`<div class="tabs">${['veterans','trainees','supports'].map(k=>`<button data-collection="${k}" class="${collection.kind===k?'active':''}">${{veterans:'Veterans',trainees:'Trainees',supports:'Support cards'}[k]} <span class="badge">${state.collections[k].length}</span></button>`).join('')}</div><div class="panel">${collection.kind==='veterans'?searchUI.markup('collection'):`<div class="toolbar"><label class="grow">Search<input id="collection-query" placeholder="Name, outfit, ID or memo…" value="${esc(collection.query)}"></label><label>Sort<select id="collection-sort">${metaOptions(['rating','name','newest','sparks','stars','level'],x=>x,x=>({rating:'Rating / rarity',name:'Name A–Z',newest:'Newest / ID',sparks:'Spark count',stars:'Spark stars',level:'Level / awakening'}[x]),collection.sort)}</select></label>${collection.kind!=='supports'?`<label>Aptitude<select id="collection-aptitude"><option value="">Any</option>${metaOptions(aptitudes,a=>a[0],a=>a[0],collection.aptitude)}</select></label><label>Minimum grade<select id="collection-grade">${metaOptions([1,2,3,4,5,6,7,8],x=>x,x=>grades[x],collection.grade)}</select></label>`:`<label>Card type<select id="collection-type"><option value="">Any</option>${metaOptions([...new Set(D.supports.map(s=>s.supportCardTypeName))],x=>x,x=>x,collection.type)}</select></label>`}</div>`} <div id="collection-rows"></div></div>`;}
function filteredRows(){if(collection.kind==='veterans'){const r=veteranSearch.run(state.collections.veterans,state.searches.collection);const status=$('[data-search-panel=collection] .search-validation');if(status){status.textContent=r.error?'Search error: '+r.error:`${r.rows.length} veterans match`;status.classList.toggle('error',!!r.error);}return r.rows;}let rows=[...state.collections[collection.kind]];const q=collection.query.toLowerCase().trim();rows=rows.filter(r=>{
 const s=collection.kind==='supports'?support(r.cardId):null,c=char(r.cardId);const name=s?`${s.charaName} ${s.supportCardTitle}`:title(r.cardId);
 if(q&&!`${name} ${r.id} ${r.cardId} ${r.memo??''}`.toLowerCase().includes(q))return false;
 if(collection.kind==='supports'&&collection.type&&s?.supportCardTypeName!==collection.type)return false;
 if(collection.kind!=='supports'&&collection.aptitude){const a=aptitudes.find(a=>a[0]===collection.aptitude),g=collection.kind==='veterans'?r.aptitudes[a[0]]:grades.indexOf(c?.[a[2]]);if(g<collection.grade)return false;}
 if(collection.kind==='veterans'&&collection.spark){const fs=collection.scope==='lineage'?[...r.sparks,...r.parents.flatMap(p=>p.sparks)]:r.sparks;if(!fs.some(f=>f.id===Number(collection.spark)&&f.stars>=collection.minStars))return false;}return true;});
 const sparkList=r=>collection.scope==='lineage'?[...(r.sparks??[]),...(r.parents??[]).flatMap(p=>p.sparks)]:r.sparks??[];
 rows.sort((a,b)=>{switch(collection.sort){case'name':return (collection.kind==='supports'?support(a.cardId)?.charaName??'':charName(a.cardId)).localeCompare(collection.kind==='supports'?support(b.cardId)?.charaName??'':charName(b.cardId));case'newest':return String(b.date??b.id).localeCompare(String(a.date??a.id),undefined,{numeric:true});case'sparks':return sparkList(b).length-sparkList(a).length;case'stars':return sparkList(b).reduce((s,f)=>s+f.stars,0)-sparkList(a).reduce((s,f)=>s+f.stars,0);case'level':return (b.level??b.talent??0)-(a.level??a.talent??0);default:return (b.rating??b.rarity??support(b.cardId)?.rarity??0)-(a.rating??a.rarity??support(a.cardId)?.rarity??0);}});return rows;
}
function renderRows(){const rows=filteredRows(),pages=Math.max(1,Math.ceil(rows.length/30));collection.page=Math.min(collection.page,pages-1);$('#collection-rows').innerHTML=rows.length?`<p class="tiny">${number(rows.length)} matching ${collection.kind}</p><div class="table-wrap"><table><thead><tr><th>${collection.kind==='supports'?'Support card':'Character'}</th><th>${collection.kind==='veterans'?'Rating / stats':collection.kind==='trainees'?'Rarity / awakening':'Level / limit breaks'}</th><th>${collection.kind==='veterans'?'Sparks':collection.kind==='supports'?'Type':'Aptitudes'}</th><th></th></tr></thead><tbody>${rows.slice(collection.page*30,collection.page*30+30).map(r=>{
 const s=support(r.cardId),c=char(r.cardId),name=collection.kind==='supports'?(s?.charaName??`Support ${r.cardId}`):charName(r.cardId),sub=collection.kind==='supports'?(s?.supportCardTitle??'Unknown card ID'):outfit(r.cardId);
 return `<tr><td class="name"><div class="roster-name">${collection.kind==='supports'?ref.supportArt(r.cardId):ref.portrait(r.cardId)}<div>${esc(name)}<span class="row-sub">${esc(sub)} · #${esc(r.id)}</span></div></div></td><td>${collection.kind==='veterans'?`${number(r.rating)}<span class="row-sub">${stats.map(k=>r.stats[k]).join(' / ')}</span>`:collection.kind==='trainees'?`${r.rarity}★ · Awakening ${r.talent}`:`Lv ${r.level??'?'} · ${r.limitBreak}/4 LB`}</td><td>${collection.kind==='veterans'?sparks(r.sparks,4):collection.kind==='supports'?esc(s?.supportCardTypeName??'Unknown'):`<span class="row-sub">${aptitudes.filter(a=>['A','S'].includes(c?.[a[2]])).map(a=>a[0]).join(' · ')||'No A aptitude data'}</span>`}</td><td><button class="small" data-detail="${esc(r.id)}">Inspect</button></td></tr>`}).join('')}</tbody></table></div><div class="pagination"><button class="small" data-page="-1" ${collection.page===0?'disabled':''}>← Previous</button><span>${collection.page+1} / ${pages}</span><button class="small" data-page="1" ${collection.page>=pages-1?'disabled':''}>Next →</button></div>`:`<div class="empty"><div class="empty-icon">▦</div><h2>${state.collections[collection.kind].length?'No matching records':'Your collection starts here'}</h2><p>${state.collections[collection.kind].length?'Try a different filter.':'Import your umadump JSON to browse names, aptitudes, skills and sparks.'}</p><button data-action="import">Import collection</button></div>`;}
function skillMarkup(s){return ref.card(s);}
function boughtMarkup(){const p=state.plan;return `<h3 class="source-heading">Skills bought on target</h3><p class="tiny">${p.includeSupports?'Deck mode chooses the highest sourced skill tier automatically; only Inspiration only below overrides it.':'Assumed learned from the career unless marked Inspiration only.'} Gold / ◎ choices change the creation base; inspiration-only skills must first be inherited. These assumptions affect Spark % mode.</p>${p.wanted.filter(id=>factor(id)?.type===3).map(id=>{const b=p.bought?.[id]??{},ids=D['skill-links'].factorSkills[id]??[],variants=ids.map(skill).filter(Boolean);const tiers=[['white',sparkName(id)]];for(const v of variants){const tier=v.rarity===2?'gold':v.skillName.endsWith('◎')?'upgraded':'white';if(!tiers.some(t=>t[0]===tier))tiers.push([tier,v.skillName]);}return `<div class="bought-skill"><b>${esc(sparkName(id))}</b><label>Expected learned version<select data-bought-tier="${id}" ${b.inspirationOnly||p.includeSupports?'disabled':''}>${metaOptions(tiers,t=>t[0],t=>t[1],b.tier??'white')}</select></label><label class="check"><input type="checkbox" data-inspiration="${id}" ${b.inspirationOnly?'checked':''}> Inspiration only</label>${D['skill-links'].factorAliases[id]?'<small>Normal / + interchangeable; each ancestor counts once.</small>':''}</div>`;}).join('')||'<p class="tiny">Add desired skill sparks to set learning assumptions.</p>'}`;}
function renderSkills(){return heading('BUNDLED GAME REFERENCE','Read the fine print.','Skill effects, activation conditions, variants, and acquisition sources.')+`<div class="panel"><div class="toolbar"><label class="grow">Search skills and conditions<input id="skill-query" placeholder="Name, ID, phase_random, effect…" value="${esc(skillQuery)}"></label><label>Category<select data-skill-filter="category"><option value="">Any category</option>${metaOptions([...new Set(D.skills.map(s=>s.skillCategory))].sort(),x=>x,x=>x,skillFilters.category)}</select></label><label>Rarity<select data-skill-filter="rarity"><option value="">Any rarity</option>${metaOptions([['normal','Normal'],['gold','Gold'],['unique','Unique']],x=>x[0],x=>x[1],skillFilters.rarity)}</select></label></div><div class="toolbar"><label>Condition / race restriction<select data-skill-filter="condition"><option value="">Any condition</option>${metaOptions(['Early race','Mid race','Late race','Final spurt','Random location','Corner','Straight','Front runner','Pace chaser','Late surger','End closer','Sprint','Mile','Medium','Long'],x=>x,x=>x,skillFilters.condition)}</select></label><label>Activation check<select data-skill-filter="wit"><option value="">Any</option>${metaOptions(['Wit check','No wit check'],x=>x,x=>x,skillFilters.wit)}</select></label><label class="check"><input type="checkbox" data-skill-filter="owned" ${skillFilters.owned?'checked':''}> Has an owned character / support source</label><button data-action="reset-skill-filters">Reset filters</button></div></div><div id="skill-rows"></div>`;}
function renderSkillRows(){const q=skillQuery.toLowerCase().trim().split(/\s+/).filter(Boolean),ownedChars=new Set(state.collections.trainees.map(x=>x.cardId)),ownedSupports=new Set(state.collections.supports.map(x=>x.cardId));const rows=D.skills.filter(s=>{const tags=ref.tags(s),text=[s.skillName,s.skillId,s.activationCondition,s.activationCondition2,s.precondition,s.precondition2,s.effectSummary,s.effectSummary2,s.skillDesc,...tags].join(' ').toLowerCase(),links=D['skill-links'].skills[s.skillId];return q.every(t=>text.includes(t))&&(!skillFilters.category||s.skillCategory===skillFilters.category)&&(!skillFilters.rarity||(skillFilters.rarity==='gold'?s.rarity===2:skillFilters.rarity==='unique'?s.skillCategory==='Unique':s.rarity===1&&s.skillCategory!=='Unique'))&&(!skillFilters.condition||tags.includes(skillFilters.condition))&&(!skillFilters.wit||tags.includes(skillFilters.wit))&&(!skillFilters.owned||['characters','characterEvents','supportHints','supportEvents'].some(k=>(links?.[k]??[]).some(x=>(k.startsWith('support')?ownedSupports:ownedChars).has(x.id))));});const pages=Math.max(1,Math.ceil(rows.length/20));skillPage=Math.min(skillPage,pages-1);$('#skill-rows').innerHTML=`<p class="tiny">${rows.length} skills · snapshot ${D.metadata.retrieved} · condition tags summarize exact expression matches</p><div class="skill-grid">${rows.slice(skillPage*20,skillPage*20+20).map(skillMarkup).join('')||'<div class="empty">No matching skills.</div>'}</div><div class="pagination"><button data-skill-page="-1" ${skillPage===0?'disabled':''}>Previous</button><span>${skillPage+1} / ${pages}</span><button data-skill-page="1" ${skillPage>=pages-1?'disabled':''}>Next</button></div>`;}
function renderData(){return heading('YOUR DATA, YOUR DEVICE','Bring your collection.','Import files directly into this browser. No account, server upload or game MDB required.')+`<div class="split"><section><div class="import-card" id="drop-zone" role="button" tabindex="0" aria-label="Import JSON files"><div class="empty-icon">⇅</div><h2>Drop your JSON files here</h2><p>or click to choose all three at once</p><span class="badge">UMADUMP · JSON ONLY</span></div><div class="panel" style="margin-top:20px"><h2>Imported collections</h2>${['trainees','supports','veterans'].map(k=>`<div class="file-row"><div><b>${{trainees:'card_data.json',supports:'support_card_data.json',veterans:'trained_chara_data.json'}[k]}</b><small>${state.collections[k].length} records${state.imports[k]?` · ${esc(state.imports[k].filename)} · ${new Date(state.imports[k].importedAt).toLocaleDateString()}`:''}</small></div><button class="small danger" data-remove-collection="${k}" ${!state.collections[k].length?'disabled':''}>Remove</button></div>`).join('')}<p class="tiny">File contents identify the collection, so trained_char_data.json works too. Reimporting replaces that collection; saved plan snapshots remain. Account IDs are not retained.</p></div><div class="panel"><h2>Backup & restore</h2><p>Back up the roster, current plan and saved plans before clearing browser data or changing devices. A backup contains your collection and personal memos.</p><div class="actions"><button data-action="export-backup">Export backup</button><button data-action="restore">Restore backup / plan</button></div></div></section><section><div class="panel"><div class="eyebrow">GAME DATA SNAPSHOT</div><h2>${D.metadata.retrieved} · Global</h2><div class="file-row"><span>Character outfits</span><b>${D.characters.length}</b></div><div class="file-row"><span>Support cards</span><b>${D.supports.length}</b></div><div class="file-row"><span>Skills with technical details</span><b>${D.skills.length}</b></div><div class="file-row"><span>Compatibility characters</span><b>${D.affinity.chars.length}</b></div><p>Names, aptitudes and skill expressions come from uma.guide’s public data bundle. Spark definitions, compatibility tables and G1 groups come from uma.moe’s public resources.</p><p>Unknown IDs remain visible. Target-specific parent search excludes characters without compatibility data; affinity-free search can include them. New game releases require refreshing the bundled snapshot; it does not silently update while you plan.</p><p><a href="https://uma.guide/roster-viewer/" target="_blank" rel="noreferrer">uma.guide ↗</a> · <a href="https://uma.moe/lineage-planner" target="_blank" rel="noreferrer">uma.moe ↗</a> · <a href="https://github.com/Werseter/umadump" target="_blank" rel="noreferrer">umadump ↗</a></p></div><div class="panel"><h2>How this app handles imports</h2><p>Records are validated before any collection is replaced. Veteran ancestry uses position IDs 10 and 20. Spark stars are decoded from factor IDs, including exports where level is zero.</p><p>Storage is local to this site and browser. Artwork loads from uma.guide, which receives image requests but not your JSON files. No telemetry or third-party scripts run here. Clearing site data removes your saved workspace.</p><div class="notice">This is an independent implementation of the requested tools, not an embedded copy of either website.</div></div></section></div>`;}
function openModal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function modalHeader(text){return `<div class="modal-top"><h2>${esc(text)}</h2><button data-action="close-modal" aria-label="Close">✕</button></div>`;}
function showPicker(index,kind){pickerIndex=index;pickerKind=kind??(index===0?'characters':'veterans');const n=state.plan.nodes[index];openModal(modalHeader(labels[index])+`<div class="tabs"><button data-picker-kind="veterans" class="${pickerKind==='veterans'?'active':''}">Imported veterans</button><button data-picker-kind="characters" class="${pickerKind==='characters'?'active':''}">Plan a character</button></div><label>Search by character, outfit or ID<input id="picker-query" placeholder="Search…" autocomplete="off"></label><div id="picker-list" class="picker-list"></div>${n.cardId?`<hr><h3>Selected: ${esc(title(n.cardId))}</h3><p class="tiny">Manual edits change this plan only. They do not change your imported veteran.</p>${sparks(n.sparks)}<div class="toolbar"><label class="grow">Spark<select id="node-factor">${metaOptions([...engine.factors.values()],f=>f.id,f=>f.text)}</select></label><label>Stars<select id="node-stars"><option>1</option><option>2</option><option selected>3</option></select></label><button data-action="node-add-spark">Add / update</button></div><div class="chips">${n.sparks.map(f=>`<button class="chip" data-node-remove-spark="${f.id}">${esc(sparkName(f.id))} ×</button>`).join('')}</div><details><summary>G1 race wins (${n.wins.length} recorded saddle IDs)</summary><p class="tiny">Selecting a G1 adds its shared-win group to this planned character.</p><div class="toolbar"><label class="grow">Race<select id="node-race">${metaOptions(uniqueRaces(),r=>r.id,r=>r.name)}</select></label><button data-action="node-add-race">Add win</button></div><div class="chips">${n.wins.map(id=>`<button class="chip" data-node-remove-race="${id}">${esc(D.races[id]?.name??`Saddle #${id}`)} ×</button>`).join('')}</div></details>`:''}`);renderPickerList();}
function uniqueRaces(){const m=new Map();Object.entries(D.races).forEach(([id,r])=>{if(!m.has(r.group))m.set(r.group,{id,...r});});return [...m.values()].sort((a,b)=>a.name.localeCompare(b.name));}
function candidateAffinity(v){let nodes;if(pickerKind==='veterans')nodes=placeVeteran(state.plan,pickerIndex,v).nodes;else {nodes=structuredClone(state.plan.nodes);nodes[pickerIndex]={...emptyNode(),cardId:v.cardId};}const issues=validateTree(nodes);if(issues.length)return {text:'Invalid relationship',value:-1,invalid:true};
 // The additional eight slots belong to a future parent's local seven-slot tree.
 let label='Lineage';if(pickerIndex>=7){const center=Math.floor((Math.floor((pickerIndex-1)/2)-1)/2);const p1=center*2+1,p2=p1+1;nodes=[center,p1,p2,p1*2+1,p1*2+2,p2*2+1,p2*2+2].map(i=>nodes[i]);label='Branch';}
 if(!nodes[0].cardId)return {text:'Choose target for affinity',value:0};const ev=engine.evaluate(nodes,state.plan.parentRaceBonus);if(nodes.some(n=>n.cardId&&!engine.index.has(baseId(n.cardId))))return {text:'Affinity unavailable',value:-1};return {text:`${label} affinity ${ev.total}${ev.complete?'':' · partial'}`,value:ev.total};}
function renderPickerList(){const q=$('#picker-query').value.toLowerCase();const rows=(pickerKind==='veterans'?veteranSearch.run(state.collections.veterans,state.searches.planner).rows.filter(v=>`${title(v.cardId)} ${v.id}`.toLowerCase().includes(q)):D.characters.filter(c=>`${c.charaName} ${c.cardTitle} ${c.cardId}`.toLowerCase().includes(q))).map(v=>({v,aff:candidateAffinity(v)})).sort((a,b)=>b.aff.value-a.aff.value);$('#picker-list').innerHTML=rows.slice(0,80).map(({v,aff})=>`<button class="pick-row" data-pick="${pickerKind==='veterans'?esc(v.id):v.cardId}" ${aff.invalid?'disabled':''}>${ref.portrait(v.cardId)}<div class="grow"><b>${esc(charName(v.cardId))}</b><span>${esc(outfit(v.cardId))}</span><span class="row-sub">${pickerKind==='veterans'?`Veteran #${esc(v.id)}`:`${state.collections.trainees.some(t=>t.cardId===v.cardId)?'Owned':'Not imported'} · ${v.cardId}`}</span></div><strong class="affinity-preview">${esc(aff.text)}</strong></button>`).join('')||'<p>No matching records. Import veterans or switch to planning a character.</p>';if(rows.length>80)$('#picker-list').insertAdjacentHTML('beforeend','<p class="tiny">Showing the best 80 matches by affinity. Narrow your search.</p>');}
function inspect(id){detailId=id;const r=state.collections[collection.kind].find(r=>r.id===id);if(!r)return;
 if(collection.kind==='veterans')openModal(modalHeader(title(r.cardId))+`${ref.portrait(r.cardId)}<p class="tiny">Veteran #${esc(r.id)} · rating ${number(r.rating)} · ${esc(r.date)}</p><div class="stat-grid">${stats.map(k=>`<div>${{wiz:'Wit'}[k]??k}<b>${r.stats[k]}</b></div>`).join('')}</div><div class="aptitudes">${aptitudes.map(a=>`<span>${a[0]} <b>${grades[r.aptitudes[a[0]]]??'?'}</b></span>`).join('')}</div><h3>Sparks</h3>${sparks(r.sparks)}<h3 style="margin-top:20px">Recorded parents</h3>${r.parents.map(p=>`<p>${esc(title(p.cardId))}</p>${sparks(p.sparks)}`).join('')||'<p>No ancestors included in this record.</p>'}<h3 style="margin-top:20px">Learned skills</h3>${r.skills.map(s=>skill(s.id)?skillMarkup(skill(s.id)):`<p>Unknown skill #${s.id}</p>`).join('')||'<p>No skills recorded.</p>'}<p>Memo: ${esc(r.memo||'—')}</p><div class="actions"><button class="primary" data-detail-place="1">Use as parent 1</button><button class="primary" data-detail-place="2">Use as parent 2</button></div>`);
 else if(collection.kind==='trainees'){const c=char(r.cardId);openModal(modalHeader(title(r.cardId))+`${ref.portrait(r.cardId)}<p>${r.rarity}★ · Awakening ${r.talent}</p><div class="aptitudes">${aptitudes.map(a=>`<span>${a[0]} <b>${esc(c?.[a[2]]??'?')}</b></span>`).join('')}</div><h3>Growth bonuses</h3><p>${['Speed','Stamina','Power','Guts','Wisdom'].map(k=>`${k}: ${c?.['talent'+k]??'?'}%`).join(' · ')}</p><button class="primary" data-target="${r.cardId}">Plan this trainee</button>`);}
 else {const s=support(r.cardId);openModal(modalHeader(`${s?.charaName??'Unknown support'} ${s?.supportCardTitle??r.cardId}`)+`${ref.supportArt(r.cardId)}<p>${esc(s?.rarityDisplay??'?')} · ${esc(s?.supportCardTypeName??'?')} · Level ${r.level??'unknown'} · ${r.limitBreak}/4 limit breaks</p><h3>Skill hints</h3>${(s?.skillHints??[]).map(h=>{const sk=skill(h.skillId);return sk?skillMarkup(sk):`<p>${esc(h.skillName??h.name??`Skill #${h.skillId}`)}</p>`}).join('')||'<p>No hints in this snapshot.</p>'}`);}
}
async function importFiles(files){try{
 const incoming=[];for(const file of files){if(file.size>35*1024*1024)throw Error(`${file.name} exceeds 35 MB.`);incoming.push(normalizeImport(JSON.parse(await file.text()),file.name,engine.factors));}
 if(new Set(incoming.map(x=>x.kind)).size!==incoming.length)throw Error('Choose only one file for each collection in a single import.');
 const next=structuredClone(state);for(const item of incoming){next.collections[item.kind]=item.data;next.imports[item.kind]={filename:item.filename,importedAt:item.importedAt};}
 // Persist before replacing the in-memory workspace; a failure leaves the old roster intact.
 await writeState(next);state=next;searchUI?.migrate();invalidate();render();notify(`Imported ${incoming.map(x=>`${x.data.length} ${x.kind}`).join(', ')}.`);
 }catch(e){notify(`Import failed: ${e.message}`);}finally{$('#import-files').value='';}}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validatePlan(p){if(!p||!Array.isArray(p.nodes)||p.nodes.length!==15||!Array.isArray(p.wanted)||!Array.isArray(p.pins)||p.pins.length!==2||![1,2].includes(p.rolls))throw Error('Invalid plan structure.');for(const n of p.nodes){if(!Number.isSafeInteger(n.cardId)||n.cardId<0||!Array.isArray(n.sparks)||!Array.isArray(n.wins)||n.wins.some(x=>!Number.isSafeInteger(x)||x<=0)||n.sparks.some(f=>!Number.isSafeInteger(f.id)||f.id<=0||![1,2,3].includes(f.stars)))throw Error('Invalid lineage node.');}if(p.wanted.some(id=>!Number.isSafeInteger(id)||id<=0))throw Error('Invalid desired sparks.');p.bought=p.bought&&typeof p.bought==='object'&&!Array.isArray(p.bought)?p.bought:{};for(const [id,b] of Object.entries(p.bought)){if(!b||!['white','upgraded','gold'].includes(b.tier??'white')||typeof(b.inspirationOnly??false)!=='boolean')throw Error('Invalid skill learning assumptions.');}p.scenario=Object.hasOwn(scenarioNames,p.scenario)?p.scenario:'auto';p.autoScenarios=Array.isArray(p.autoScenarios)?p.autoScenarios.filter(k=>Object.hasOwn(scenarioNames,k)):['URA','Aoharu','MANT','GL'];p.trainingFocus=['balanced','speed','stamina','power','guts','wisdom'].includes(p.trainingFocus)?p.trainingFocus:'balanced';p.trainingWeight=Number.isFinite(Number(p.trainingWeight??25))?Math.max(0,Math.min(100,Number(p.trainingWeight??25))):25;p.training=p.training&&Number.isFinite(p.training.score)&&Array.isArray(p.training.comparisons)&&Array.isArray(p.training.missing)?p.training:null;p.includeSupports=!!p.includeSupports;p.borrowSSR=p.borrowSSR!==false;p.deck=Array.isArray(p.deck)?p.deck.filter(c=>Number.isSafeInteger(c.id)).slice(0,6):[];p.searchMode=p.searchMode==='sparkgen'?'sparkgen':'inherit';delete p.minChance;p.name=String(p.name??'Imported plan').slice(0,200);return p;}
async function restore(file){try{if(file.size>50*1024*1024)throw Error('Backup exceeds 50 MB.');const incoming=JSON.parse(await file.text());let next;
 if(incoming.format==='umaplan-plan'&&incoming.version===1){next=structuredClone(state);next.plan=validatePlan(incoming.plan);}
 else if(incoming.format==='umaplan-backup'&&incoming.version===1){next=incoming.workspace;if(next?.schema!==1||!next.collections||!next.imports||!Array.isArray(next.saved))throw Error('Invalid workspace.');validatePlan(next.plan);next.saved.forEach(validatePlan);for(const k of ['trainees','supports','veterans']){if(!Array.isArray(next.collections[k])||next.collections[k].length>30000)throw Error('Invalid collections.');for(const r of next.collections[k]){if(!r||typeof r.id!=='string'||!Number.isSafeInteger(r.cardId)||r.cardId<=0)throw Error('Invalid collection record.');if(k==='veterans'){if(!Array.isArray(r.parents)||!r.stats||!r.aptitudes||!Array.isArray(r.skills))throw Error('Invalid veteran.');for(const v of [r,...r.parents]){if(!Array.isArray(v.sparks)||!Array.isArray(v.wins)||v.sparks.some(f=>!Number.isSafeInteger(f.id)||![1,2,3].includes(f.stars)))throw Error('Invalid veteran sparks.');}}}}}
 else throw Error('This is not a Umaplan backup or plan. Use Import collection for umadump files.');
 openModal(modalHeader('Restore this file?')+`<p>${incoming.format==='umaplan-backup'?'This replaces this browser’s collections, current plan, and saved plans.':'This replaces only the current plan.'} Export a backup first if you want to keep the existing workspace.</p><div class="actions"><button class="primary" id="confirm-restore">Restore</button><button data-action="close-modal">Cancel</button></div>`);
 $('#confirm-restore').onclick=async()=>{try{await writeState(next);state=next;searchUI?.migrate();invalidate();$('#modal').close();render();notify('Restored successfully.');}catch(e){notify(`Restore failed: ${e.message}`);}};
 }catch(e){notify(`Restore failed: ${e.message}`);}finally{$('#backup-file').value='';}}
function findParents(){const filtered=veteranSearch.run(state.collections.veterans,state.searches.planner);if(filtered.error){notify(filtered.error);return;}if(state.plan.pins.some((pin,i)=>pin&&!filtered.rows.some(v=>v.id===state.plan.nodes[i+1].sourceId))){notify('A pinned parent is excluded by the candidate filters. Adjust filters or unpin it.');return;}if(worker)worker.terminate();worker=new Worker(new URL('./search-worker.js',import.meta.url),{type:'module'});const status=$('#search-status');status.innerHTML='<p>Searching eligible pairs…</p><div class="progress"><span style="width:2%"></span></div><button class="small" data-action="cancel-search">Cancel search</button>';worker.onmessage=({data})=>{const el=$('#search-status');if(data.type==='progress'){if(el)el.innerHTML=`<p class="tiny">${number(data.checked)} comparisons</p><div class="progress"><span style="width:${data.checked/data.total*100}%"></span></div><button class="small" data-action="cancel-search">Cancel</button>`;}else{worker.terminate();worker=null;if(data.type==='error'){if(el)el.textContent=data.message;notify(data.message);}else{results=data;if(el)el.innerHTML=`<p class="tiny">Complete · ${number(data.matched)} matching pairs.</p>`;renderResults();$('#results')?.scrollIntoView({behavior:'smooth',block:'start'});}}};worker.onerror=e=>{notify(`Search failed: ${e.message}`);worker?.terminate();worker=null;if($('#search-status'))$('#search-status').textContent='Search failed.';};worker.postMessage({affinity:D.affinity,factors:D.factors,races:D.races,links:D['skill-links'],plan:{...state.plan,borrowSSR:state.plan.borrowSSR!==false},veterans:filtered.rows,supports:D.supports,ownedSupports:state.collections.supports,skills:D.skills,characters:D.characters});}
const actions={
 'reset-skill-filters':()=>{Object.assign(skillFilters,{category:'',rarity:'',condition:'',wit:'',owned:false});skillQuery='';skillPage=0;render();},
 import:()=>$('#import-files').click(),restore:()=>$('#backup-file').click(),'close-modal':()=>$('#modal').close(),
 'new-plan':()=>{state.saved.push({...structuredClone(state.plan),name:`${state.plan.name} (previous)`});state.plan=emptyPlan();invalidate();render();notify('Started a new plan; the previous plan was saved.');},
 'export-plan':()=>download('umaplan-lineage.json',{format:'umaplan-plan',version:1,plan:state.plan}),
 'export-backup':()=>download('umaplan-backup.json',{format:'umaplan-backup',version:1,workspace:state}),
 'save-plan':()=>{state.plan.name=($('#plan-name').value.trim()||'Untitled lineage').slice(0,200);state.saved.push(structuredClone(state.plan));save();render();notify('Saved a plan snapshot.');},
 'add-wanted':()=>{const text=$('#wanted-search').value.trim(),match=text.match(/\(#(\d+)\)$/),id=match?Number(match[1]):[...engine.factors].find(([id,f])=>f.text.toLowerCase()===text.toLowerCase()||String(id)===text)?.[0];if(!id||!factor(id)){notify('Choose a spark from the suggestions.');return;}if(!state.plan.wanted.includes(id))state.plan.wanted.push(id);invalidate();render();},
 'find-parents':findParents,'cancel-search':()=>{worker?.terminate();worker=null;if($('#search-status'))$('#search-status').textContent='Search cancelled.';},
 'node-add-spark':()=>{const id=Number($('#node-factor').value),stars=Number($('#node-stars').value),n=state.plan.nodes[pickerIndex];n.sparks=n.sparks.filter(f=>f.id!==id);n.sparks.push({id,stars});n.sourceId=null;invalidate();render();showPicker(pickerIndex,pickerKind);},
 'node-add-race':()=>{const id=Number($('#node-race').value),n=state.plan.nodes[pickerIndex];if(!n.wins.includes(id))n.wins.push(id);n.winsKnown=true;n.sourceId=null;invalidate();render();showPicker(pickerIndex,pickerKind);}
};
document.addEventListener('click',e=>{if(searchUI?.handle(e))return;const el=e.target.closest('button,[data-action],#drop-zone');if(!el)return;try{
 if(el.id==='header-import'||el.id==='drop-zone')return actions.import();
 if(el.dataset.action)return actions[el.dataset.action]?.();
 if(el.dataset.skillSources)return openModal(modalHeader(`Sources · ${skill(el.dataset.skillSources)?.skillName}`)+ref.sources(Number(el.dataset.skillSources)));
 if(el.dataset.skillVariants)return openModal(modalHeader(`Variants · ${skill(el.dataset.skillVariants)?.skillName}`)+ref.variants(Number(el.dataset.skillVariants)));
 if(el.dataset.edit!==undefined)return showPicker(Number(el.dataset.edit));
 if(el.dataset.clearNode!==undefined){state.plan.nodes[Number(el.dataset.clearNode)]=emptyNode();invalidate();return render();}
 if(el.dataset.pickerKind){return showPicker(pickerIndex,el.dataset.pickerKind);}
 if(el.dataset.pick){if(pickerKind==='veterans'){const v=state.collections.veterans.find(v=>v.id===el.dataset.pick);const next=placeVeteran(state.plan,pickerIndex,v);const issues=validateTree(next.nodes);if(issues.length){notify(issues[0]);return;}state.plan=next;}else{const next=structuredClone(state.plan);next.nodes[pickerIndex]={...emptyNode(),cardId:Number(el.dataset.pick)};const issues=validateTree(next.nodes);if(issues.length){notify(issues[0]);return;}state.plan=next;}invalidate();render();showPicker(pickerIndex,pickerKind);return;}
 if(el.dataset.nodeRemoveSpark){const n=state.plan.nodes[pickerIndex];n.sparks=n.sparks.filter(f=>f.id!==Number(el.dataset.nodeRemoveSpark));n.sourceId=null;invalidate();render();return showPicker(pickerIndex,pickerKind);}
 if(el.dataset.nodeRemoveRace){const n=state.plan.nodes[pickerIndex];n.wins=n.wins.filter(id=>id!==Number(el.dataset.nodeRemoveRace));n.sourceId=null;invalidate();render();return showPicker(pickerIndex,pickerKind);}
 if(el.dataset.removeWanted){state.plan.wanted=state.plan.wanted.filter(id=>id!==Number(el.dataset.removeWanted));invalidate();return render();}
 if(el.dataset.loadPlan!==undefined){state.plan=structuredClone(state.saved[Number(el.dataset.loadPlan)]);invalidate();return render();}
 if(el.dataset.deletePlan!==undefined){state.saved.splice(Number(el.dataset.deletePlan),1);save();return render();}
 if(el.dataset.applyPair!==undefined){const result=results.top[Number(el.dataset.applyPair)];let next=structuredClone(state.plan);next.deck=result.deck??[];next.training=result.training??null;for(const [slot,id] of [[1,result.a],[2,result.b]])next=placeVeteran(next,slot,state.collections.veterans.find(v=>v.id===id));state.plan=next;invalidate();render();notify('Applied parent pair and their recorded ancestors.');return;}
 if(el.dataset.collection){collection.kind=el.dataset.collection;collection.page=0;collection.query='';return render();}
 if(el.dataset.page){collection.page+=Number(el.dataset.page);return renderRows();}
 if(el.dataset.skillPage){skillPage+=Number(el.dataset.skillPage);renderSkillRows();window.scrollTo({top:0});return;}
 if(el.dataset.detail)return inspect(el.dataset.detail);
 if(el.dataset.detailPlace){state.plan=placeVeteran(state.plan,Number(el.dataset.detailPlace),state.collections.veterans.find(v=>v.id===detailId));invalidate();$('#modal').close();location.hash='planner';render();return;}
 if(el.dataset.target){state.plan.nodes[0]={...emptyNode(),cardId:Number(el.dataset.target)};invalidate();$('#modal').close();location.hash='planner';return;}
 if(el.dataset.removeCollection){const k=el.dataset.removeCollection;openModal(modalHeader(`Remove ${k}?`)+`<p>This removes the imported ${k} from this browser. Saved lineage snapshots remain.</p><div class="actions"><button class="danger" id="confirm-remove">Remove collection</button><button data-action="close-modal">Cancel</button></div>`);$('#confirm-remove').onclick=()=>{state.collections[k]=[];delete state.imports[k];invalidate();$('#modal').close();render();};return;}
 }catch(err){notify(err.message);}});
document.addEventListener('input',e=>{if(searchUI?.handle(e))return;const el=e.target;if(el.id==='picker-query')renderPickerList();if(el.id==='collection-query'){collection.query=el.value;collection.page=0;renderRows();}if(el.id==='skill-query'){skillQuery=el.value;skillPage=0;renderSkillRows();}});
document.addEventListener('change',e=>{if(searchUI?.handle(e))return;const el=e.target;
 if(el.dataset.pin!==undefined){state.plan.pins[Number(el.dataset.pin)]=el.checked;invalidate();}
 if(el.id==='parent-race'){state.plan.parentRaceBonus=el.checked;invalidate();render();}
 if(el.id==='rolls'){state.plan.rolls=Number(el.value);invalidate();render();}
 if(el.dataset.autoScenario){const a=new Set(state.plan.autoScenarios??['URA','Aoharu','MANT','GL']);el.checked?a.add(el.dataset.autoScenario):a.delete(el.dataset.autoScenario);state.plan.autoScenarios=[...a];invalidate();render();}
 if(['training-scenario','training-focus','training-weight'].includes(el.id)){state.plan[{'training-scenario':'scenario','training-focus':'trainingFocus','training-weight':'trainingWeight'}[el.id]]=el.id==='training-weight'?Number(el.value):el.value;invalidate();render();}
 if(el.id==='include-supports'||el.id==='borrow-ssr'){state.plan[el.id==='include-supports'?'includeSupports':'borrowSSR']=el.checked;invalidate();render();}
 if(el.id==='search-mode'){state.plan.searchMode=el.value;invalidate();render();}
 if(el.dataset.boughtTier||el.dataset.inspiration){const id=el.dataset.boughtTier??el.dataset.inspiration;state.plan.bought??={};const b=state.plan.bought[id]??={tier:'white',inspirationOnly:false};if(el.dataset.boughtTier)b.tier=el.value;else {b.inspirationOnly=el.checked;if(el.checked)b.tier='white';}invalidate();render();}
 if(el.dataset.skillFilter){skillFilters[el.dataset.skillFilter]=el.type==='checkbox'?el.checked:el.value;skillPage=0;renderSkillRows();}
 const map={'collection-sort':'sort','collection-aptitude':'aptitude','collection-grade':'grade','collection-spark':'spark','collection-stars':'minStars','collection-scope':'scope','collection-type':'type'};
 if(map[el.id]){collection[map[el.id]]=['grade','minStars'].includes(map[el.id])?Number(el.value):el.value;collection.page=0;renderRows();}
 if(el.id==='import-files')importFiles([...el.files]);if(el.id==='backup-file'&&el.files[0])restore(el.files[0]);
});
document.addEventListener('error',e=>{if(e.target.matches?.('.art img')){e.target.hidden=true;e.target.parentElement.classList.add('art-missing');}},true);
document.addEventListener('dragover',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();$('#drop-zone').classList.add('drag');}});
document.addEventListener('dragleave',e=>{if(e.target.closest('#drop-zone'))$('#drop-zone').classList.remove('drag');});
document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();importFiles([...e.dataTransfer.files]);}});
document.addEventListener('keydown',e=>{if(e.target.id==='drop-zone'&&['Enter',' '].includes(e.key)){e.preventDefault();actions.import();}});
window.addEventListener('hashchange',go);
async function boot(){try{const names=['characters','supports','skills','factors','races','affinity','metadata','skill-links'];D=Object.fromEntries(await Promise.all(names.map(async n=>{const r=await fetch(`./data/${n}.json`);if(!r.ok)throw Error(`Could not load ${n}.json (${r.status}).`);return[n,await r.json()];})));engine=new Engine(D.affinity,D.factors,D.races,D['skill-links']);ref=createReference(D,esc);try{state=await readState()??initial();validatePlan(state.plan);}catch(e){state=initial();notify('Could not restore local data. Import a backup if you have one.');}veteranSearch=createVeteranSearch(D,engine);searchUI=createSearchUI({service:veteranSearch,esc,getState:()=>state,notify,changed:(refresh=true)=>{plannerFiltersOpen=$('#planner-filters')?.open??plannerFiltersOpen;collection.page=0;invalidate();if(refresh)render();else{const key=route==='collection'?'collection':'planner',r=veteranSearch.run([],state.searches[key]),status=$(`[data-search-panel=${key}] .search-validation`);if(status){status.textContent=r.error?'Search error: '+r.error:'Filters ready';status.classList.toggle('error',!!r.error);}if(route==='collection')renderRows();if($('#results'))$('#results').innerHTML='';}}});searchUI.migrate();$('#snapshot').textContent=`Global snapshot · ${D.metadata.retrieved}`;go();}catch(e){$('#main').innerHTML=`<div class="empty"><h1>Unable to load Umaplan</h1><p>${esc(e.message)}</p><p>Open the app through GitHub Pages or a local HTTP server, rather than opening index.html directly.</p><button onclick="location.reload()">Retry</button></div>`;}}
boot();
